using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        if (Vector256.IsHardwareAccelerated)
        {
            IncrementAboveVector256(data, threshold);
        }
        else if (Vector128.IsHardwareAccelerated)
        {
            IncrementAboveVector128(data, threshold);
        }
        else
        {
            IncrementAboveScalar(data, threshold);
        }
    }

    private static void IncrementAboveVector256(Span<int> data, int threshold)
    {
        var thresholdVec = Vector256.Create(threshold);
        var oneVec = Vector256.Create(1);

        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int limit = data.Length - Vector256<int>.Count;

        while (i <= limit)
        {
            var vec = Vector256.LoadUnsafe(ref start, (nuint)i);
            // CompareGreaterThan produces -1 (all bits set) for elements > threshold
            var mask = Vector256.GreaterThan(vec, thresholdVec);
            // -1 & 1 == 1, so masked increment adds 1 only where condition is true
            vec += (mask & oneVec);
            Vector256.StoreUnsafe(vec, ref start, (nuint)i);
            i += Vector256<int>.Count;
        }

        // Scalar remainder
        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }

    private static void IncrementAboveVector128(Span<int> data, int threshold)
    {
        var thresholdVec = Vector128.Create(threshold);
        var oneVec = Vector128.Create(1);

        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int limit = data.Length - Vector128<int>.Count;

        while (i <= limit)
        {
            var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
            var mask = Vector128.GreaterThan(vec, thresholdVec);
            vec += (mask & oneVec);
            Vector128.StoreUnsafe(vec, ref start, (nuint)i);
            i += Vector128<int>.Count;
        }

        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }

    private static void IncrementAboveScalar(Span<int> data, int threshold)
    {
        for (int i = 0; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

